/**
 * スイスのクイズ(現時点は3問のみ。承認後に100〜120問まで増やす)。
 *
 * 難易度は他の盤面と同じ1〜10。都市カード(5件)が扱った具体的な事実
 * (ベルンの「憲法は首都と呼ばない」/ジュネーブの国連加盟が2002年/
 * シュヴィーツの連邦憲章/アンデルマットの爆破装薬/キアッソの難民政策)は
 * ここでは問わない。
 *
 * 3問目(難易度9)の「レデュイ・ナシオナル」という名称そのものは、
 * アンデルマットの都市カードには書いていない(カードは計画の中身だけを
 * 説明し、名称は伏せてある)ので重複ではない。年号(1940年7月)は
 * 一般に知られたスイス近代史の事実だが、一次資料までは当たっていない。
 * **確度: 中〜高。念のため他盤面の担当に確認を依頼したい。**
 */
function t(source) {
  const parts = source.split("|");
  if (parts.length !== 4) {
    throw new Error(`4言語(en|es|fr|ja)で書いてください: ${source.slice(0, 60)}…`);
  }
  const [en, es, fr, ja] = parts;
  return { en, es, fr, ja };
}

/** 1問を組み立てる。`o` は選択肢の配列、`a` は正解の添字。 */
function q(difficulty, question, options, a, fact) {
  return { difficulty, q: t(question), o: options.map(t), a, f: t(fact) };
}

